import secrets
import string

def generate(length):
    if not 16 <= length <= 128:
        raise ValueError("Length must be 16..128")
    alphabet = string.ascii_letters + string.digits + "!@#%-_"
    return "".join(secrets.choice(alphabet) for _ in range(length))

print("Generated length:", len(generate(20)))

from decimal import Decimal

def minor_units(text):
    value = Decimal(text)
    if not value.is_finite() or value < 0:
        raise ValueError("Invalid amount")
    cents = value * 100
    if cents != cents.to_integral_value():
        raise ValueError("Use at most two decimal places")
    return int(cents)

print(minor_units("10.10") + minor_units("0.20"))

def parse_weather(data):
    current = data["current"]
    temperature = current["temperature_2m"]
    if not isinstance(temperature, (int, float)):
        raise ValueError("Temperature is not numeric")
    return {"temperature": temperature, "time": current["time"]}

# Parser-only example, not a live weather response.
