def validate_messages(messages):
    if not 1 <= len(messages) <= 12:
        raise ValueError("Invalid message count")
    for message in messages:
        if message["role"] not in ("user", "assistant"):
            raise ValueError("Invalid role")
        if not 1 <= len(message["content"]) <= 4000:
            raise ValueError("Invalid content length")
    return messages

print(validate_messages([{"role": "user", "content": "Explain loops"}]))

def summary(values):
    if not values:
        return {"count": 0, "total": 0, "average": None}
    if any(not isinstance(v, (int, float)) for v in values):
        raise ValueError("Numeric values required")
    return {"count": len(values), "total": sum(values), "average": sum(values) / len(values)}

print(summary([10, 20, 30]))

